#!/bin/sh
':' //; exec "${BUN:-bun}" "$0" "$@"
// vapor-exact's commands: `bun exact.mjs --help` lists the verbs, `bun exact.mjs <verb> --help` a verb's flags.
// They live in the exact2 checkout named by EXACT2 (default ../../../exact-vapor), in its
// scripts/app-cli.mjs. Generated by `exact new`; `bun exact.mjs update` rewrites this file, the crates.io
// patches, the toolchain and the exact2 dependency paths. The app's own verbs are app.json's `commands`.
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

const EXACT2 = resolve(import.meta.dir, process.env.EXACT2 ?? "../../../exact-vapor");
const cli = resolve(EXACT2, 'scripts/app-cli.mjs');
if (!existsSync(cli)) {
  console.error(`no exact2 at ${EXACT2} (no scripts/app-cli.mjs): EXACT2 names the checkout`);
  process.exit(1);
}
const { ensureBun } = await import(resolve(EXACT2, 'scripts/bun.mjs'));
ensureBun("1.4.2");
const { run } = await import(cli);
process.exit(await run({ dir: import.meta.dir, name: "vapor-exact", exact2: EXACT2, args: process.argv.slice(2) }));
